
.shell {
  --bg: linear-gradient(180deg, rgba(16, 21, 34, 0.96), rgba(11, 10, 17, 0.98));
  --panel: rgba(255, 255, 255, 0.05);
  --line: rgba(230, 197, 123, 0.24);
  --gold: #e6c57b;
  --pale: #efe2bf;
  --text: #f5efe3;
  --text-soft: #bfb7aa;
  width: 100%;
  max-width: 780px;
  margin: 8px auto;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  color: var(--text);
  background:
    radial-gradient(circle at top right, rgba(182, 69, 69, 0.16), transparent 28%),
    radial-gradient(circle at top left, rgba(230, 197, 123, 0.18), transparent 24%), var(--bg);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow:
    0 18px 40px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  font-family: Georgia, 'Times New Roman', serif;
}

.hero,
.section-title,
.card-top,
.name-row,
.outer-head,
.event-head,
.duo {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.hero {
  padding: 14px;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.05), rgba(182, 69, 69, 0.08));
  border: 1px solid var(--line);
  border-radius: 14px;
}

.hero-main h1 {
  margin: 4px 0 6px;
  font-size: 24px;
  letter-spacing: 0.04em;
}

.hero-main p,
.info-block p,
.thought p,
.event-card p,
.outer-card p {
  margin: 0;
  color: var(--text-soft);
  line-height: 1.55;
}

.eyebrow {
  font-size: 10px;
  letter-spacing: 0.28em;
  color: var(--gold);
}

.hero-side {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: flex-end;
}

.spot,
.badge,
.outer-tags span,
.involved span {
  padding: 4px 9px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.05);
  font-size: 11px;
}

.world-grid,
.event-grid,
.protagonist-grid,
.detail-grid,
.outer-grid,
.stats-grid,
.thoughts {
  display: grid;
  gap: 10px;
}

.world-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.protagonist-grid,
.detail-grid,
.event-grid,
.outer-grid,
.thoughts {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.stats-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.metric-card,
.info-block,
.character-card,
.event-card,
.outer-card,
.stat-box,
.outer-box {
  background: var(--panel);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
}

.metric-card,
.info-block,
.event-card,
.outer-card,
.stat-box,
.outer-box,
.character-card,
.thought {
  padding: 12px;
}

.metric-card strong,
.stat-box strong,
.duo strong {
  font-size: 22px;
  color: var(--pale);
}

.danger strong {
  color: #ffb2b2;
}

.metric-label,
.label,
.section-title small,
.subline {
  font-size: 11px;
  color: var(--text-soft);
}

.meter {
  height: 6px;
  border-radius: 999px;
  margin-top: 8px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
}

.fill {
  height: 100%;
  border-radius: inherit;
}

.gold {
  background: linear-gradient(90deg, #8a6832, #e6c57b);
}

.blue {
  background: linear-gradient(90deg, #304966, #6d8db6);
}

.red {
  background: linear-gradient(90deg, #5e1b1b, #c96262);
}

.section-title {
  margin-bottom: 10px;
}

.section-title span {
  font-size: 16px;
  color: var(--gold);
}

.tab-row,
.subline,
.badges,
.outer-tags,
.involved {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.tab {
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-soft);
  border-radius: 999px;
  padding: 6px 12px;
  cursor: pointer;
}

.tab.active {
  background: linear-gradient(135deg, rgba(230, 197, 123, 0.22), rgba(182, 69, 69, 0.24));
  color: var(--text);
  border-color: var(--line);
}

.name-row h2 {
  margin: 0;
  font-size: 24px;
}

.stage {
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(230, 197, 123, 0.12);
  border: 1px solid rgba(230, 197, 123, 0.22);
  font-size: 12px;
}

.outer-box summary {
  cursor: pointer;
  color: var(--gold);
}

.thought ul {
  margin: 8px 0 0;
  padding-left: 18px;
  color: var(--text-soft);
}

.protagonist-full {
  grid-column: 1 / -1;
}

@media (max-width: 640px) {
  .hero,
  .card-top {
    flex-direction: column;
  }

  .hero-side {
    align-items: flex-start;
  }

  .world-grid,
  .protagonist-grid,
  .detail-grid,
  .event-grid,
  .outer-grid,
  .thoughts,
  .stats-grid {
    grid-template-columns: 1fr;
  }
}
